    if (x.to == me.em) return no('You cannot pay a refund to yourself.');
    if (x.from) return no('The vehicle owner holds this deposit and refunds it directly.');
    const m = p.method == 'Cash' ? 'Cash' : 'GCash',
      ref = str(p.ref, 30);
