      settled = r2(S.pay.filter(p => p.kind == 'owner_remit' && p.payer == em && p.status == 'Verified').reduce((s, p) => s + p.amount, 0)),
      sent = r2(S.pay.filter(p => p.kind == 'owner_remit' && p.payer == em && p.status == 'Submitted').reduce((s, p) => s + p.amount, 0));
