      bid: b.id,
      cat: x.cat,
      sev: x.sev,
      w: x.w || now().slice(0, 16),
      d: x.d,
      ph: x.phs[0] || '',
      phs: x.phs,
      ...(x.blot ? { blot: x.blot } : {}),
