      bal: h.turnBal(em),
      overdue: h.turnOverdue(em),
      trips: tripsOf(em).map(b => ({ id: b.id, cd: b.cd, fare: h.splitOf(b).fare, held: held(b), share: h.splitOf(b).drv, owner: (h.U(tripOwner(b)) || {}).name || '' })),
