      const drv = p.drv === undefined || p.drv === '' || p.drv === null ? +(v.rent || {}).drv || 0 : Math.round(+p.drv);
      if (!(drv == 0 || (drv >= 300 && drv <= 20000))) return no('Set the driver rate between ₱300 and ₱20,000 a day, or 0 for self-drive only.');
