    h.au(me.em, 'vehicle ' + p.act, { vehicle: v.id });
    h.ntf(
      v.owner,
      'Vehicle ' + v.approval.toLowerCase(),
      `${v.brand} ${v.model} (${v.plate}) was ${v.approval.toLowerCase()}.${p.act != 'approve' ? ' Reason: ' + reason : ''}${extra}`
    );
